PROGRAM alarm_ctrl
VAR_INPUT
    Trip : BOOL;
    Reset : BOOL;
END_VAR
VAR_OUTPUT
    Alarm : BOOL;
END_VAR
VAR
    latched_alarm : BOOL;
END_VAR

IF Trip THEN
    latched_alarm := TRUE;
END_IF;

IF Reset AND NOT Trip THEN
    latched_alarm := FALSE;
END_IF;

Alarm := latched_alarm;
END_PROGRAM

