    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR
    State : INT := 0;
    LIQ_MIN : INT := 10;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
    T1 : TON;
END_VAR

IF NOT EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSIF StartBatch AND State = 0 THEN
    State := 1;
ELSIF State = 1 AND Level >= LVL_HIGH AND Level >= LIQ_MIN THEN
    State := 2;
ELSIF State = 2 AND Temp >= TEMP_SET AND Level >= LIQ_MIN THEN
    State := 3;
ELSIF State = 3 AND T1.Q >= PT_REACT THEN
    State := 4;
ELSIF State = 4 AND Level <= LVL_LOW AND Level >= LIQ_MIN THEN
    State := 0;
END_IF;

CASE State OF
    0:
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
    1:
        FillValve := Level < LVL_HIGH AND Level >= LIQ_MIN;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
    2:
        FillValve := FALSE;
        Heater := Temp < TEMP_SET AND Level >= LIQ_MIN;
        Agitator := Heater;
        DrainValve := FALSE;
    3:
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
        T1(IN := TRUE, PT := PT_REACT);
    4:
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := Level > LVL_LOW AND Level >= LIQ_MIN;
END_CASE;

END_PROGRAM

