ELSIF State = 3 AND TON1.Q THEN
    State := 4;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSIF State = 4 AND Level <= LVL_LOW THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
END_IF;

CASE State OF
    0: FillValve := FALSE; Heater := FALSE; Agitator := FALSE; DrainValve := FALSE;
    1: FillValve := TRUE; Heater := FALSE; Agitator := FALSE; DrainValve := FALSE;
    2: FillValve := FALSE; Heater := TRUE; Agitator := TRUE; DrainValve := FALSE;
    3: FillValve := FALSE; Heater := TRUE; Agitator := TRUE; DrainValve := FALSE;
    4: FillValve := FALSE; Heater := FALSE; Agitator := FALSE; DrainValve := TRUE;
END_CASE;

TON1(IN := TRUE, PT := PT_REACT);

IF Level < LIQ_MIN OR Level > 100 OR (State = 1 AND State = 4) OR EStop THEN
    FillValve := FALSE;
    Heater := FALSE;
