END_VAR
CASE State OF
    0: // Idle
        IF StartBatch AND EStop THEN
            State := 1;
        END_IF;
    1: // Fill
        FillValve := TRUE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
        IF Level >= LVL_HIGH OR NOT EStop THEN
            State := 2;
        END_IF;
    2: // Heat
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
        IF Temp >= TEMP_SET OR NOT EStop THEN
            State := 3;
        END_IF;
    3: // React
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
        IF NOT EStop THEN
            IF NOT TON(T_1, PT_REACT).Q THEN
                TON(T_1, PT_REACT);
                State := 4;
            END_IF;
        ELSE
            State := 0;
        END_IF;
    4: // Drain
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := TRUE;
        IF Level <= LVL_LOW OR NOT EStop THEN
            State := 0;
        END_IF;
END_CASE;

// Safety conditions
IF FillValve AND DrainValve OR NOT EStop OR Level < LIQ_MIN THEN
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
