    TEMP_SET : CONSTANT INT := 100;
    PT_REACT : CONSTANT TIME := T#3s;
    T1 : TON;
END_VAR

IF NOT EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSIF StartBatch AND Level >= LIQ_MIN THEN
    CASE State OF
        0: // Idle
            IF StartBatch THEN
                State := 1;
                T1(IN := TRUE, PT := T#1s);
            ELSE
                State := 0;
            END_IF;

        1: // Fill
            FillValve := TRUE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
            IF Level >= LVL_HIGH OR T1.Q THEN
                State := 2;
                T1(IN := FALSE);
            END_IF;

        2: // Heat
            FillValve := FALSE;
            Heater := TRUE;
            Agitator := TRUE;
            DrainValve := FALSE;
            IF Temp >= TEMP_SET THEN
                State := 3;
                T1(IN := TRUE, PT := PT_REACT);
            END_IF;

        3: // React
            FillValve := FALSE;
            Heater := TRUE;
            Agitator := TRUE;
            DrainValve := FALSE;
            IF T1.Q THEN
                State := 4;
                T1(IN := FALSE);
            END_IF;

        4: // Drain
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := TRUE;
            IF Level <= LVL_LOW THEN
                State := 0;
            END_IF;
    END_CASE;
END_IF;

// Safety conditions
IF FillValve AND DrainValve THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
END_IF;

IF NOT EStop AND (Heater OR Agitator) AND Level < LIQ_MIN THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
END_IF;
END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
