    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR
    State : INT := 0;
    LIQ_MIN : INT := 10;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
    T1 : TON;
END_VAR

IF NOT EStop THEN
    State := 0;
END_IF;

CASE State OF
    0: // Idle
        IF StartBatch AND Level >= LIQ_MIN THEN
            State := 1;
        END_IF;
    1: // Fill
        IF Level >= LVL_HIGH OR NOT EStop THEN
            State := 2;
        ELSE
            FillValve := TRUE;
        END_IF;
    2: // Heat
        IF Temp >= TEMP_SET AND Level >= LIQ_MIN THEN
            IF Level < LVL_HIGH AND NOT EStop THEN
                State := 1;
            ELSE IF Temp < TEMP_SET AND Level >= LIQ_MIN THEN
                State := 2;
            ELSE
                State := 3;
            END_IF;
        ELSE
            Heater := TRUE;
            Agitator := TRUE;
        END_IF;
    3: // React
        IF T1.Q AND Level >= LIQ_MIN THEN
            State := 4;
        ELSE
            T1(IN := TRUE, PT := PT_REACT);
        END_IF;
    4: // Drain
        IF Level <= LVL_LOW OR NOT EStop THEN
            State := 0;
        ELSE
            DrainValve := TRUE;
        END_IF;
END_CASE;

// Safety conditions
IF (FillValve AND DrainValve) OR NOT EStop OR (Heater AND Level < LIQ_MIN) OR (Agitator AND Level < LIQ_MIN) THEN
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
END_IF;

