PROGRAM star_delta
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    MainK : BOOL;
    StarK : BOOL;
    DeltaK : BOOL;
END_VAR
VAR CONSTANT
    PT_STAR : TIME := T#3s;
END_VAR
VAR
    State : INT := 0;
END_VAR

CASE State OF
    0: // Off
        IF StartPB AND EStop THEN
            State := 1;
            MainK := TRUE;
            StarK := TRUE;
            DeltaK := FALSE;
        END_IF;

    1: // Star
        IF NOT EStop OR StopPB THEN
            State := 0;
            MainK := FALSE;
            StarK := FALSE;
            DeltaK := FALSE;
        ELSIF PT_STAR.TON() THEN
            PT_STAR(IN := TRUE, PT := PT_STAR);
            State := 2;
            MainK := TRUE;
            StarK := FALSE;
            DeltaK := TRUE;
        END_IF;

    2: // Delta
        IF NOT EStop OR StopPB THEN
            State := 0;
            MainK := FALSE;
            StarK := FALSE;
            DeltaK := FALSE;
        END_IF;

END_CASE;

END_PROGRAM

PROGRAM star_delta
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    MainK : BOOL;
    StarK : BOOL;
    DeltaK : BOOL;
END_VAR
VAR CONSTANT
    PT_STAR : TIME := T#3s;
END_VAR
VAR
    State : INT := 0;
    StarTimer : TON;
END_VAR

CASE State OF
    0: // Off
        MainK := FALSE;
        StarK := FALSE;
        DeltaK := FALSE;
        IF StartPB AND EStop THEN
            State := 1;
        END_IF;

    1: // Star
        MainK := TRUE;
        StarK := TRUE;
        DeltaK := FALSE;
        StarTimer(IN := TRUE, PT := PT_STAR);
        IF StopPB OR NOT EStop OR StarTimer.Q THEN
            State := 0;
        ELSIF StarTimer.Q THEN
            State := 2;
        END_IF;

    2: // Delta
        MainK := TRUE;
        StarK := FALSE;
        DeltaK := TRUE;
        IF StopPB OR NOT EStop THEN
            State := 0;
        END_IF;
END_CASE;

// Safety condition: never energize both StarK and DeltaK simultaneously
IF StarK AND DeltaK THEN
    StarK := FALSE;
    DeltaK := FALSE;
END_IF;

END_PROGRAM

