                State := 1;
            END_IF;
        1: // Filling
            IF Level >= 90 THEN
                State := 2;
            END_IF;
            Pump := TRUE;
            Valve := FALSE;
        2: // Draining
            IF Level <= 10 THEN
                State := 0;
            END_IF;
