        END_IF;
    1: // Pre-purge
        PurgeTimer(IN := TRUE, PT := PT_PURGE);
        IF PurgeTimer.Q THEN
            State := 2;
        END_IF;
    2: // Ignition trial
        IgniteTimer(IN := TRUE, PT := PT_IGN);
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := TRUE;
        IF IgniteTimer.Q THEN
            IF Flame THEN
                State := 3;
            ELSE
                State := 0;
            END_IF;
        END_IF;
    3: // Run
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := FALSE;
        IF NOT Flame OR StopPB OR NOT EStop THEN
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

