PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT := 0;
    SeqTimer1 : TON;
    SeqTimer2 : TON;
END_VAR

SeqTimer1(IN := TRUE, PT := T#2s);
SeqTimer2(IN := TRUE, PT := T#2s);

CASE State OF
    0:
        C1 := FALSE;
        C2 := FALSE;
        C3 := FALSE;
        IF StartPB AND EStop THEN
            State := 1;
        END_IF;
    1:
        C1 := FALSE;
        C2 := FALSE;
        C3 := TRUE;
        IF SeqTimer1.Q AND EStop THEN
            State := 2;
        END_IF;
    2:
        C1 := FALSE;
        C2 := TRUE;
        C3 := TRUE;
        IF SeqTimer2.Q AND EStop THEN
            State := 3;
        END_IF;
    3:
        C1 := TRUE;
        C2 := TRUE;
        C3 := TRUE;
        IF StopPB OR NOT EStop THEN
            State := 0;
        END_IF;
END_CASE;

IF StopPB OR NOT EStop THEN
    State := 0;
END_IF;

END_PROGRAM

PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT;
    T1 : TON;
    T2 : TON;
END_VAR

IF NOT EStop OR StopPB THEN
    State := 0;
    T1(IN := FALSE);
    T2(IN := FALSE);
ELSIF StartPB AND State = 0 THEN
    State := 1;
    T1(IN := TRUE, PT := T#2s);
    C3 := TRUE;
ELSIF T1.Q AND State = 1 THEN
    State := 2;
    T2(IN := TRUE, PT := T#2s);
    C2 := TRUE;
ELSIF T2.Q AND State = 2 THEN
    State := 3;
    C1 := TRUE;
    C2 := TRUE;
    C3 := TRUE;
END_IF;

END_PROGRAM

PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT;
    T1 : TON;
    T2 : TON;
END_VAR

IF NOT EStop THEN
    CASE State OF
        0:
            IF StartPB AND NOT StopPB THEN
                State := 1;
                T1(IN := TRUE, PT := T#2s);
            END_IF;
        1:
            IF T1.Q THEN
                State := 2;
                T2(IN := TRUE, PT := T#2s);
            END_IF;
        2:
            IF T2.Q AND StartPB AND NOT StopPB THEN
                State := 3;
            END_IF;
        3:
            IF StopPB OR NOT StartPB THEN
                State := 0;
            END_IF;
    END_CASE;

    C1 := State >= 3;
    C2 := State >= 2;
    C3 := State >= 1;
ELSE
    C1 := FALSE;
    C2 := FALSE;
    C3 := FALSE;
    State := 0;
END_IF;

END_PROGRAM

PROGRAM conveyor3
VAR_INPUT
