    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT;
    SeqTimer1 : TON;
    SeqTimer2 : TON;
END_VAR

SeqTimer1(IN := NOT EStop AND StartPB AND State <= 0, PT := T#2s);
SeqTimer2(IN := NOT EStop AND StartPB AND (State = 1 OR State = 2), PT := T#2s);

CASE State OF
